package com.example.riskplatform.controller;import com.example.riskplatform.common.ApiResponse;import com.example.riskplatform.dto.Requests.CompanyRequest;import com.example.riskplatform.entity.Company;import com.example.riskplatform.service.CompanyService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/companies") @RequiredArgsConstructor public class CompanyController{private final CompanyService s;@GetMapping @PreAuthorize("hasAuthority('company:read')")public ApiResponse<List<Company>>list(@RequestParam(required=false)String keyword){return ApiResponse.ok(s.list(keyword));}@GetMapping("/{id}") @PreAuthorize("hasAuthority('company:read')")public ApiResponse<Company>get(@PathVariable Long id){return ApiResponse.ok(s.get(id));}@PostMapping @PreAuthorize("hasAuthority('company:write')")public ApiResponse<Company>create(@Valid @RequestBody CompanyRequest r){return ApiResponse.ok(s.create(r));}@PutMapping("/{id}") @PreAuthorize("hasAuthority('company:write')")public ApiResponse<Company>update(@PathVariable Long id,@Valid @RequestBody CompanyRequest r){return ApiResponse.ok(s.update(id,r));}@DeleteMapping("/{id}") @PreAuthorize("hasAuthority('company:write')")public ApiResponse<Void>delete(@PathVariable Long id){s.delete(id);return ApiResponse.ok();}}